def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Split the grid into horizontal bands that contain non-background cells.
    active = [any(v != bg for v in row) for row in grid]
    bands = []
    r = 0
    while r < h:
        if not active[r]:
            r += 1
            continue
        start = r
        while r < h and active[r]:
            r += 1
        bands.append((start, r))

    if len(bands) >= 2 and len({b - a for a, b in bands}) == 1:
        bh = bands[0][1] - bands[0][0]
        # The fullest band is the reference pattern.
        ref = max(bands, key=lambda ab: sum(v != bg for row in grid[ab[0]:ab[1]] for v in row))
        ref_rows = grid[ref[0]:ref[1]]
        for a, b in bands:
            if (a, b) == ref:
                continue
            # Find the rightmost whole column that agrees with the reference.
            last_same = -1
            for c in range(w):
                if all(grid[a + rr][c] == ref_rows[rr][c] for rr in range(bh)):
                    last_same = c
            # In the differing suffix, mark missing foreground cells.
            for c in range(last_same + 1, w):
                for rr in range(bh):
                    if grid[a + rr][c] == bg and ref_rows[rr][c] != bg:
                        out[a + rr][c] = 1

